import "dotenv/config";
import { Client } from "pg";
import { pathToFileURL } from "node:url";
const identifier = (v: string) => '"' + v.replaceAll('"', '""') + '"';
const literal = (v: string) => "'" + v.replaceAll("'", "''") + "'";
// Explicit operator operation. A fresh role cannot inherit application privileges.
export async function provisionAdminRole(
  owner: Client,
  adminUrl: string,
  schema = "public",
) {
  const url = new URL(adminUrl);
  const role = decodeURIComponent(url.username),
    password = decodeURIComponent(url.password);
  if (!/^[a-z][a-z0-9_]{2,62}$/.test(role) || password.length < 24)
    throw new Error("ADMIN_ROLE_CONFIGURATION_INVALID");
  const current = await owner.query(
    "SELECT current_user AS name, current_database() AS db",
  );
  if (
    role === current.rows[0].name ||
    decodeURIComponent(url.pathname.slice(1)) !== current.rows[0].db
  )
    throw new Error("ADMIN_ROLE_CONFIGURATION_INVALID");
  if (
    (await owner.query("SELECT 1 FROM pg_roles WHERE rolname=$1", [role]))
      .rowCount
  )
    throw new Error("ADMIN_ROLE_ALREADY_EXISTS");
  const r = identifier(role),
    s = identifier(schema);
  await owner.query("BEGIN");
  try {
    await owner.query(
      `CREATE ROLE ${r} LOGIN PASSWORD ${literal(password)} NOSUPERUSER NOCREATEDB NOCREATEROLE NOINHERIT NOREPLICATION NOBYPASSRLS`,
    );
    await owner.query(
      `GRANT CONNECT ON DATABASE ${identifier(current.rows[0].db)} TO ${r}`,
    );
    await owner.query(`GRANT USAGE ON SCHEMA ${s} TO ${r}`);
    await owner.query(
      `GRANT SELECT (id,email,name,"createdAt",plan,"subscriptionStatus","currentPeriodStart","currentPeriodEnd","dodoSubscriptionId","gracePeriodEnd","cancelAtPeriodEnd","planOverride","planOverrideStartsAt","planOverrideExpiresAt","grandfatheredUntil","isSuspended","suspendedAt","deletionRequestedAt","gmailAuthorized","lastActiveAt","isAdmin","usageBackfillVersion","usageCutoverAt","testingUsageResetAt") ON ${s}."User" TO ${r}`,
    );
    await owner.query(
      `GRANT UPDATE ("planOverride","planOverrideStartsAt","planOverrideExpiresAt","planOverrideReason","isSuspended","suspendedAt","suspensionReason") ON ${s}."User" TO ${r}`,
    );
    for (const table of [
      "UsagePeriod",
      "UsageReservation",
      "UsageImportEvidence",
      "BillingRateLimit",
      "AdminAuditSafe",
      "AdminSendMetadata",
      "AdminReceiptMetadata",
    ])
      await owner.query(`GRANT SELECT ON ${s}.${identifier(table)} TO ${r}`);
    await owner.query(
      `GRANT SELECT (id,"userId",status) ON ${s}."Campaign" TO ${r}`,
    );
    await owner.query(`GRANT UPDATE (status) ON ${s}."Campaign" TO ${r}`);
    await owner.query(
      `GRANT UPDATE (status,"deliveryState","cancelledAt","claimToken","leaseExpiresAt",error) ON ${s}."Send" TO ${r}`,
    );
    await owner.query(
      `GRANT SELECT (id,"campaignId",status,"deliveryState","attemptedAt","sentAt") ON ${s}."Send" TO ${r}`,
    );
    await owner.query(
      `GRANT UPDATE (sent,reserved,"importedSent","importedReserved","operationalEndsAt") ON ${s}."UsagePeriod" TO ${r}`,
    );
    await owner.query(`GRANT INSERT ON ${s}."UsagePeriod" TO ${r}`);
    await owner.query(
      `GRANT UPDATE (status,"releasedAt") ON ${s}."UsageReservation" TO ${r}`,
    );
    await owner.query(
      `GRANT SELECT (id,key,"sendingEnabled","paidGatingEnabled","updatedAt") ON ${s}."SystemControl" TO ${r}`,
    );
    await owner.query(
      `GRANT UPDATE ("sendingEnabled","updatedAt") ON ${s}."SystemControl" TO ${r}`,
    );
    await owner.query(
      `GRANT INSERT ON ${s}."AdminAuditLog", ${s}."BillingRateLimit" TO ${r}`,
    );
    await owner.query(
      `GRANT UPDATE ("requestCount") ON ${s}."BillingRateLimit" TO ${r}`,
    );
    await grantHardeningBudgets(owner, role, schema);
    // PUBLIC grants can undermine a fresh role too. Refuse unsafe databases.
    for (const [table, column] of [
      ["User", "encryptedRefreshToken"],
      ["User", "googleId"],
      ["Send", "body"],
      ["Send", "subject"],
      ["Send", "recipientEmail"],
    ]) {
      const check = await owner.query(
        "SELECT has_column_privilege($1,$2,$3,'SELECT') AS allowed",
        [role, `${s}.${identifier(table)}`, column],
      );
      if (check.rows[0].allowed) throw new Error("ADMIN_ROLE_UNSAFE");
    }
    for (const table of [
      "Contact",
      "Template",
      "Attachment",
      "BillingWebhookEvent",
      "AdminAuditLog",
    ]) {
      const check = await owner.query(
        "SELECT has_table_privilege($1,$2,'SELECT') AS allowed",
        [role, `${s}.${identifier(table)}`],
      );
      if (check.rows[0].allowed) throw new Error("ADMIN_ROLE_UNSAFE");
    }
    await owner.query("COMMIT");
  } catch {
    await owner.query("ROLLBACK");
    throw new Error("ADMIN_ROLE_PROVISION_FAILED");
  }
}
export async function grantHardeningBudgets(
  owner: Client,
  role: string,
  schema = "public",
) {
  if (!/^[a-z][a-z0-9_]{2,62}$/.test(role))
    throw new Error("ADMIN_ROLE_CONFIGURATION_INVALID");
  const s = identifier(schema),
    r = identifier(role);
  await owner.query(
    `GRANT SELECT, INSERT, UPDATE ON ${s}."RateLimitBucket" TO ${r}`,
  );
}
async function main() {
  const owner = new Client({ connectionString: process.env.DATABASE_URL });
  try {
    if (!process.env.ADMIN_DATABASE_URL) throw new Error();
    await owner.connect();
    if (process.argv.includes("--upgrade-hardening"))
      await grantHardeningBudgets(
        owner,
        decodeURIComponent(new URL(process.env.ADMIN_DATABASE_URL).username),
      );
    else await provisionAdminRole(owner, process.env.ADMIN_DATABASE_URL);
    console.info("ADMIN_ROLE_PROVISIONED");
  } catch {
    console.error("ADMIN_ROLE_PROVISION_FAILED");
    process.exitCode = 1;
  } finally {
    await owner.end();
  }
}
if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href)
  void main();
